	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/devices/{device_id}", wrapper.RevokeDevice)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/api/v1/devices/{device_id}", wrapper.UpdateDevice)
